const LOKVAANI_STORAGE_KEY = "kathavrnta_lokvaani_user_posts_v4";

const LOKVAANI_STORAGE = {
  getEntries() {
    try {
      localStorage.removeItem("kathavrnta_lokvaani_data_v1");
      localStorage.removeItem("kathavrnta_lokvaani_data_v2");
      localStorage.removeItem("kathavrnta_lokvaani_data_v3");
      const custom = JSON.parse(localStorage.getItem(LOKVAANI_STORAGE_KEY));
      const validCustom = Array.isArray(custom) ? custom : [];
      return [...validCustom, ...LOKVAANI_DATA];
    } catch (e) {
      return LOKVAANI_DATA;
    }
  },

  addEntry(entryObj) {
    const newEntry = {
      id: "lv-user-" + Date.now(),
      title: entryObj.title || "Custom Oral Heritage Entry",
      form: entryObj.form || "Story",
      formLabel: entryObj.formLabel || entryObj.form || "Oral Heritage",
      author: entryObj.author || "Community Contributor",
      state: entryObj.state || "Rajasthan",
      region: entryObj.region || entryObj.state,
      festival: entryObj.festival || "Folk Fair",
      description: entryObj.description || entryObj.hindiTranslation || "User submitted entry.",
      fullStory: entryObj.fullStory || entryObj.context || "User submitted oral heritage lore.",
      keywords: [entryObj.title, entryObj.author, entryObj.state, entryObj.form].map(s => (s || "").toLowerCase()),
      timestamp: Date.now()
    };

    try {
      const custom = JSON.parse(localStorage.getItem(LOKVAANI_STORAGE_KEY));
      const validCustom = Array.isArray(custom) ? custom : [];
      validCustom.unshift(newEntry);
      localStorage.setItem(LOKVAANI_STORAGE_KEY, JSON.stringify(validCustom));
    } catch (e) {
      console.warn("Storage addEntry error:", e);
    }
    return newEntry;
  }
};
